#!/usr/bin/env python3
"""Repair only 24 flagged L16 objects. Preserve the 84 accepted objects exactly."""
import copy,json,hashlib
from pathlib import Path
import sympy as sp
R=Path(__file__).resolve().parents[1]
def rd(p):return json.loads((R/p).read_text())
def wr(p,x):(R/p).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
def qh(q):return hashlib.sha256(json.dumps({k:v for k,v in q.items() if k not in ('status','reviewIds')},sort_keys=True,separators=(',',':'),ensure_ascii=False).encode()).hexdigest()
p='data/question-batches/archive/W04-L16-v1.json'
if not (R/p).exists():wr(p,rd('data/question-batches/W04-L16.json'))
b=rd(p);old=copy.deepcopy(b);reviews=rd('data/reviews/W04-L16-v1-independent-contracts.json');flag={x['questionId'] for x in reviews if x['decision']=='flagged'};assert len(flag)==24
qs={q['id']:q for q in b['questions']};changed=[]
def q(short):return qs['W04-L16-'+short]
def opts(short,texts,reasons):
 x=q(short)
 for o in x['options']:o['text']=texts[int(o['id'][1:])-1]
 x['solution']['optionExplanations']={f'o{i+1}':('Correct. ' if i==0 else 'Incorrect. ')+v for i,v in enumerate(reasons)}
 x['solution'].update(justification=reasons[0],simpleExplanation=reasons[0],misconceptions=reasons[1:])
for x in b['questions']:
 if x['id'] in flag:
  x.update(version=2,status='draft',reviewIds=[],revisionAuthors=sorted(set(x.get('revisionAuthors',[])+['L16-author-20261019'])))
  if x.get('conflictResolution'):x['conflictResolution']['questionVersion']=2
  changed.append(x)
opts('P0476-Q03',['An intermediate kinematic joint-limit constraint','The endpoint-position constraints, despite both endpoints being reached','A dynamic torque limit, solely because an angle bound was crossed','A derivative-continuity constraint, solely because an angle bound was crossed'],['Joint-angle bounds apply along the entire path, not just at its endpoints.','The stated endpoints are reached; the violation occurs between them.','No torque value or bound is supplied, so this cannot be diagnosed as a torque-limit failure.','A smooth trajectory can cross an angle limit without a derivative jump.'])
x=q('P0478-Q04');reason='The stated acceleration is continuous, so it has no acceleration impulse; a jump in jerk affects a higher derivative, not an impulsive acceleration.';x['solution']['optionExplanations']['o3']='Incorrect. '+reason;x['solution']['misconceptions'][1]=reason
opts('P0479-Q02',['M, V and G are continuous and no added effort term is discontinuous','Only M is continuous; V and G may have finite jumps','All model terms are bounded, although some may be discontinuous','The kinematics are C2, although an added external effort has a jump'],['Continuous kinematics composed with continuous finite model terms yield continuous effort when no additional jump is present.','Continuity of M alone does not remove possible V or G jumps.','Boundedness does not imply continuity; bounded terms can still jump.','A discontinuous external effort can make the total required actuator effort discontinuous.'])
opts('P0480-Q04',['Prescribing a straight-line tool-tip route between two poses','Interpolating already specified joint angles without prescribing the tool route','Synchronizing joint arrival times without prescribing Cartesian geometry','Imposing a separate joint-angle profile on each actuator'],['This directly specifies task-space geometry, which Cartesian planning controls explicitly.','This is a direct joint-space interpolation task.','Timing coordination alone does not prescribe the tool path.','Independent joint-coordinate profiles are a joint-space specification.'])
x=q('P0480-Q05');x['difficulty']='easy';x['cognitiveSkill']='recall';x['assumptions']=['Use differentiable forward kinematics x=f(θ) and compatible task coordinates. Define J(θ)=∂f/∂θ, the corresponding coordinate Jacobian.'];ci=copy.deepcopy(x['citations'][0]);ci.update(slideId='lectures-p0482',physicalPage=482,kind='derivation',locator='Printed slide 10: forward-kinematics equation x(t)=f(Θ(t))',evidenceText=(R/'sources/text/lectures/page-0482.txt').read_text().strip(),role='premise');x['citations'].append(ci);x['citations'][0]['role']='premise';x['solution']['steps']=['Differentiate x(t)=f(θ(t)) with the multivariable chain rule.','With J=∂f/∂θ, obtain ẋ=J(θ)θ̇.']
opts('P0486-Q01',['Use one cubic on each consecutive interval [t_i,t_{i+1}]','Use one global cubic and assume it can meet any number of arbitrary via data','Use one polynomial per joint and omit the interval-by-interval via constraints','Fit separate intervals without requiring their shared endpoint to equal the via position'],['Each consecutive via-point pair defines one segment with its own boundary data.','A single cubic has only four coefficients and cannot generally fit arbitrarily many independent via constraints.','A per-joint polynomial alone does not guarantee all supplied via positions.','The shared via position is part of both adjacent segment constraints.'])
opts('P0486-Q02',['Endpoint velocities must also be assigned or determined by additional conditions','The via times alone uniquely determine every endpoint slope','Position continuity supplies four independent conditions for each segment','The adjacent secant slopes automatically determine a unique acceleration-continuous join'],['Two positions per segment leave two cubic degrees of freedom until rate or other matching conditions are supplied.','Times locate the endpoints but do not fix their derivatives.','Position continuity does not provide both endpoint velocity conditions.','Secant rates need an explicitly chosen rule; they do not automatically enforce C2 matching.'])
x=q('P0488-Q03');x['stem']='Let R=θf−θ0−v0T and S=vf−v0, so a2T²+a3T³=R and 2a2T+3a3T²=S, with T>0. Divide the first equation by T² and the second by T, then subtract twice the first from the second. What remains?';x['assumptions']=['θ0,θf are endpoint angles; v0,vf are endpoint angular velocities; T is duration in seconds; a2,a3 are cubic coefficients. R has angle units and S has angle/time units.']
x=q('P0488-Q04');x['stem']='Define R=θf−θ0−v0T and S=vf−v0. For θ0=1 rad, θf=5 rad, v0=1 rad/s, vf=0 rad/s and T=2 s, what are R and S?'
for short in ['P0488-Q04','P0490-Q03','P0491-Q05','P0492-Q04','P0499-Q02','P0499-Q06','P0501-Q02']:
 x=q(short);x['difficulty']='easy';x['cognitiveSkill']='numerical' if x['type']=='numerical' else 'algorithm' if x['type']=='code_output' else 'application' if x['type']=='diagram' else 'recall'
opts('P0492-Q01',['User-specified velocities, heuristic assignment, acceleration-continuous spline','User-specified velocities, heuristic assignment, independent position-only interpolation','User-specified velocities, mandatory zero rates at every via point, one global straight line','Acceleration-continuous spline, fixed average rate at every endpoint, identical rates for every joint'],['These are the three methods named by the source.','Position-only interpolation does not replace the listed acceleration-continuous spline method.','The source does not restrict every via rate to zero or prescribe one global line.','Fixed identical or average rates are not the three alternatives in the source.'])
opts('P0492-Q02',['Solve J(θ_v) q̇_v=ẋ_v for feasible joint rates at the via configuration','Use q̇_v=J(θ_v)ẋ_v because the same multiplication works in either direction','Use a Jacobian evaluated at a different configuration without checking whether it has changed','Assume J(θ_v) has a unique ordinary inverse even when it is singular or rectangular'],['The joint boundary rate must realize the desired task velocity at the actual via configuration.','J maps joint rates to task rates; reverse mapping requires a compatible solve, and dimensions may prohibit that multiplication.','The Jacobian generally depends on configuration, so another pose can give the wrong rate mapping.','Singular or rectangular Jacobians need feasibility and solution-selection treatment, not an assumed unique ordinary inverse.'])
x=q('P0492-Q02');x['assumptions']=['θ_v is the via joint configuration, q̇_v its joint-rate vector, ẋ_v the specified task velocity, and J(θ_v) the compatible task-coordinate Jacobian. All quantities use consistent frames. A feasible rate solution is required.'];x['solution']['steps']=['Evaluate the task-velocity map at the via configuration.','Solve J(θ_v)q̇_v=ẋ_v under the appropriate rank and feasibility conditions.']
x=q('P0492-Q03');x.update(type='numerical',cognitiveSkill='numerical',difficulty='medium',stem='An incoming cubic is θ_L(u)=1+3u+2u²+u³ for 0≤u≤2 s. The next segment uses local time v and θ_R(v)=23+23v+bv²+cv³, so position and velocity already match at the join. What b makes acceleration match?')
x['assumptions']=['Joint position is in radians; u and v are local times in seconds. Each numerical polynomial coefficient carries the corresponding rad/s^k units. b has units rad/s² and c has units rad/s³.']
opts('P0492-Q03',['8 rad/s²','16 rad/s²','2 rad/s²','4 rad/s²'],['The incoming acceleration at u=2 is 4+6×2=16 rad/s²; the outgoing initial acceleration is 2b, so b=8.','This equates b, rather than 2b, to the required acceleration.','This copies the incoming quadratic coefficient and omits its cubic contribution at the join.','This uses the incoming initial acceleration as b rather than the actual join acceleration.'])
x['solution']['steps']=['Differentiate θ_L twice: a_L=4+6u.','At u=2, a_L=16 rad/s².','Differentiate θ_R twice: a_R=2b+6cv. At its start v=0, a_R=2b.','Set 2b=16, giving b=8 rad/s².'];x['solution']['formulas']=[dict(expression='a_L=4+6u; a_R=2b+6cv',variables={'a_L,a_R':'left/right angular accelerations','u,v':'segment-local times','b,c':'outgoing quadratic/cubic coefficients'},units={'a_L,a_R':'rad/s²','u,v':'s','b':'rad/s²','c':'rad/s³','4':'rad/s²','6 (coefficient of u)':'rad/s³'},assumptions=x['assumptions'])]
opts('P0495-Q04',['Blend the velocity transitions over a nonzero interval','Increase the duration but retain instantaneous switching to the nonzero ramp slope','Increase the plotting sample count without changing the trajectory','Change the polynomial label without changing its coefficients or endpoint slopes'],['A transition interval can replace the instantaneous velocity step.','For any finite duration and nonzero displacement, an unblended constant slope still jumps from the stationary hold.','Sampling changes the display, not the mathematical discontinuity.','Renaming an unchanged ramp does not alter its derivatives.'])
x=q('P0496-Q02');reason='The velocity row 2a2+15a3=0 is valid after division by five. The position row is invalid because the same division requires a right-hand side of 12, not 60.';x['solution']['optionExplanations']['o3']='Incorrect. '+reason;x['solution']['misconceptions'][1]=reason
opts('P0499-Q05',['np.linalg.solve raises a singular-matrix linear-algebra error','It returns a zero coefficient vector as the unique solution','It automatically switches to a least-squares solution without a different function call','It raises Python ZeroDivisionError before reaching the linear algebra solver'],['The zero coefficient matrix cannot satisfy B=[60,0]; solve reports a singular matrix.','The zero vector does not satisfy the nonzero right-hand side.','np.linalg.solve does not silently call a least-squares alternative.','The code forms powers and products of tf; it does not divide by tf before calling solve.'])
opts('P0500-Q04',[r'To preserve backslashes for the math-text commands','To convert the numeric angles automatically to radians','To substitute Python variables into the text automatically','To enable a separate external TeX engine automatically'],['A raw Python string preserves the backslash sequences that Matplotlib interprets as math text.','A string prefix does not change numeric data units.','Raw strings are not formatted strings and do not interpolate variables automatically.','External TeX rendering requires separate configuration, not the r prefix.'])
opts('P0500-Q05',['tight_layout() adjusts subplot spacing; show() requests figure display','tight_layout() rescales every data array to [0,1]; show() requests display','tight_layout() adjusts spacing; show() saves a named PNG automatically','tight_layout() saves the figure; show() only computes new axis limits'],['Layout adjustment and display are their roles in this source program.','tight_layout changes arrangement, not the data values.','File saving requires an explicit saving command and filename; show does not supply them.','tight_layout is not a file-saving command, and show requests display.'])
# Replace the duplicated summary item with the missing general-quintic angle, retaining its stable ID.
x=q('P0502-Q03');x.pop('conflictResolution',None);x.update(type='numerical',cognitiveSkill='numerical',difficulty='medium',stem='A general quintic on 0≤t≤1 s is θ(t)=1+2t+3t²+a3t³+a4t⁴+a5t⁵ radians. It must end at θ(1)=5 rad, θ̇(1)=0 rad/s and θ̈(1)=2 rad/s². Which coefficient triple (a3,a4,a5) satisfies all three final conditions?')
x['assumptions']=['t is in seconds; coefficients a3,a4,a5 have units rad/s³, rad/s⁴ and rad/s⁵. The initial conditions are θ(0)=1 rad, θ̇(0)=2 rad/s and θ̈(0)=6 rad/s², so neither endpoint acceleration is assumed zero.']
opts('P0502-Q03',['(20, −37, 16)','(19, −35, 15)','(22, −41, 18)','(18, −33, 14)'],['All three final equations are satisfied; in particular 6+6×20+12×(−37)+20×16=2 rad/s².','This satisfies final position and velocity but gives final acceleration 0 rather than 2 rad/s².','This satisfies final position and velocity but gives final acceleration 6 rather than 2 rad/s².','This satisfies final position and velocity but gives final acceleration −2 rather than 2 rad/s².'])
x['solution']['steps']=['Position at t=1 gives a3+a4+a5=−1.','Velocity gives 3a3+4a4+5a5=−8.','Acceleration gives 6a3+12a4+20a5=−4, since the initial quadratic term contributes 6.','Subtract three times the first equation from the second: a4+2a5=−5.','Combining this with the acceleration equation gives a5=16, then a4=−37 and a3=20.','Check final values: θ=5 rad, velocity=0 rad/s, acceleration=2 rad/s².'];x['solution']['formulas']=[dict(expression='θ̈(t)=6+6a3t+12a4t²+20a5t³',variables={'θ̈':'joint acceleration','t':'local time','a3,a4,a5':'quintic coefficients'},units={'θ̈':'rad/s²','t':'s','a3':'rad/s³','a4':'rad/s⁴','a5':'rad/s⁵','6 (constant term)':'rad/s²'},assumptions=x['assumptions'])]
x['citations']=[copy.deepcopy(next(c for c in q('P0493-Q01')['citations'] if c['physicalPage']==493))];x['citations'][0].update(kind='derivation',role='premise');x['subtopic']='Quintic boundary control'
# Include the explicit forward map and derivative premises for the revised applications.
for short,page,loc in [('P0492-Q02',482,'forward-kinematics equation x(t)=f(Θ(t))'),('P0492-Q03',487,'first and second derivatives of a cubic')]:
 z=q(short);ci=copy.deepcopy(z['citations'][0]);ci.update(slideId=f'lectures-p{page:04}',physicalPage=page,kind='derivation',role='premise',locator=f'Printed slide {page-472}: {loc}',evidenceText=(R/f'sources/text/lectures/page-{page:04}.txt').read_text().strip());z['citations'].append(ci)

# Keep reciprocal concept links and attach the summary page to the actual quintic concept.
oldcid=x['conceptIds'][0];newcid=q('P0493-Q01')['conceptIds'][0];x['conceptIds']=[newcid]
for c in b['concepts']:
 if c['id']==oldcid:c['questionIds']=[i for i in c['questionIds'] if i!=x['id']]
 if c['id']==newcid and x['id'] not in c['questionIds']:c['questionIds'].append(x['id'])
 for qid in c['questionIds']:
  oldq=next(z for z in old['questions'] if z['id']==qid)
  c['examinationAngles']=[qs[qid]['stem'] if s==oldq['stem'] else s for s in c.get('examinationAngles',[])]
# Refresh all concept angle lists to exactly the linked questions, without changing any accepted question.
for c in b['concepts']:c['examinationAngles']=[qs[i]['stem'] for i in c['questionIds']]
accepted=[x for x in old['questions'] if x['id'] not in flag];assert len(accepted)==84
for a in accepted:assert a==qs[a['id']]
assert all(x['correctOptionIds']==next(y for y in old['questions'] if y['id']==x['id'])['correctOptionIds'] for x in changed)
t=sp.symbols('t');polys=[1+2*t+3*t*t+a*t**3+b4*t**4+c5*t**5 for a,b4,c5 in [(20,-37,16),(19,-35,15),(22,-41,18),(18,-33,14)]]
results=[[sp.diff(p,t,k).subs(t,1) for k in range(3)] for p in polys];assert results==[[5,0,2],[5,0,0],[5,0,6],[5,0,-2]]
assert sp.diff(1+3*t+2*t*t+t**3,t,2).subs(t,2)==16
wr('data/question-batches/W04-L16.json',b)
blind=[{**{k:x[k] for k in ('id','version','stem','selectionMode','type','difficulty','options','assumptions')},'citations':[{k:v for k,v in ci.items() if k!='evidenceText'} for ci in x['citations']]} for x in changed]
wr('audits/blind-W04-L16-v2.json',blind);h=hashlib.sha256((R/'audits/blind-W04-L16-v2.json').read_bytes()).hexdigest()
wr('audits/W04-L16-v2-review-manifest.json',dict(batchId='W04-L16',blindPacketSha256=h,questionSha256={x['id']:qh(x) for x in changed},preservedAcceptedHashes={x['id']:qh(x) for x in accepted},preservedAcceptedCount=84,independentReviewPending=True))
wr('audits/W04-L16-v2-author-repair.json',dict(changedCount=24,preservedAcceptedCount=84,acceptedObjectsUnchanged=True,allKeysUnchanged=True,quinticFinalTriples=[[str(v) for v in row] for row in results],incomingAcceleration='16 rad/s²',requiredOutgoingQuadraticCoefficient='8 rad/s²',symbolicChecksPassed=True,flags={r['questionId']:r['findings'] for r in reviews if r['decision']=='flagged'}))
(R/'audits/handoffs/W04-L16-v2.md').write_text(f'# L16 v2 frozen\n\n24 revised questions, all 84 accepted objects/hashes unchanged. Total remains108. Missing general quintic with nonzero endpoint accelerations replaces redundant P0502-Q03; redundant P0492-Q03 becomes a concrete segment-coefficient matching calculation. All keys unchanged. Blind packet audits/blind-W04-L16-v2.json SHA256 {h}; manifest audits/W04-L16-v2-review-manifest.json. Exact symbolic checks passed. No self-approval, canonical or Git writes. Reproduce only with scripts/repair_W04_L16_v2.py; never rerun the v1 author script over current repairs.\n')
